 public static function activate(){if(!wp_next_scheduled(self::CRON)){ $first=strtotime('tomorrow 03:17');wp_schedule_event($first?:time()+HOUR_IN_SECONDS,'daily',self::CRON);} $d=['new_per_day'=>60,'seo_per_day'=>60,'refresh_per_day'=>60,'auto_publish'=>0,'city'=>'مكة المكرمة','keywords'=>"صيانة مكيفات\nغسيل مكيفات\nتنظيف مكيفات\nتركيب مكيفات\nفك ونقل وتركيب مكيف\nصيانة مكيفات سبليت\nصيانة مكيفات مركزية\nغسيل مكيفات شباك\nصيانة داكت وكونسيلد\nشحن فريون المكيف",'openai_key'=>'','openai_model'=>'gpt-4o-mini','refresh_after_days'=>30,'last_run'=>'','last_result'=>''];if(!get_option(self::OPT))add_option(self::OPT,$d,'',false);/* Do not create or assign pages automatically: activation must not take over the site's homepage. */}
