 private static function create_pages(){foreach([['title'=>'أكسجين للصيانة والتبريد','slug'=>'oxygen-ac-home','content'=>'[oxygen_ac_home]'],['title'=>'مقالات أكسجين لصيانة المكيفات','slug'=>'oxygen-ac-articles','content'=>'[oxygen_ac_articles]'],['title'=>'دخول إدارة أكسجين','slug'=>'oxygen-admin','content'=>'[oxygen_admin_portal]']] as $p){if(!get_page_by_path($p['slug'],OBJECT,'page'))wp_insert_post(['post_type'=>'page','post_status'=>'publish','post_title'=>$p['title'],'post_name'=>$p['slug'],'post_content'=>$p['content']]);}}
 private static function set_homepage(){$home=get_page_by_path('oxygen-ac-home',OBJECT,'page');if(!$home||$home->post_status!=='publish')return;update_option('show_on_front','page');update_option('page_on_front',(int)$home->ID);update_option('oxygen_ac_homepage_assigned','1',false);}
 public function ensure_homepage(){self::create_pages();if(get_option('oxygen_ac_homepage_assigned')!=='1')self::set_homepage();if(get_option('oxygen_ac_rewrite_version')!=='1'){flush_rewrite_rules(false);update_option('oxygen_ac_rewrite_version','1',false);}}
 public function restore_homepage_if_owned(){
  // Older versions of this plugin forcibly assigned oxygen-ac-home as the WordPress front page.
  // Undo only that assignment; if the owner selected another page afterwards, leave it untouched.
  if(get_option('oxygen_ac_homepage_assigned')!=='1')return;
  $front=(int)get_option('page_on_front');
  if($front>0 && get_post_field('post_name',$front)==='oxygen-ac-home'){
   update_option('show_on_front','posts');
   update_option('page_on_front',0);
  }
  delete_option('oxygen_ac_homepage_assigned');
  delete_option('oxygen_ac_rewrite_version');
 }
 public function ensure_daily_schedule(){if(wp_next_scheduled(self::CRON))return;$tz=function_exists('wp_timezone')?wp_timezone():new DateTimeZone(get_option('timezone_string')?:'UTC');$next=(new DateTimeImmutable('now',$tz))->modify('tomorrow')->setTime(3,17,0);wp_schedule_event($next->getTimestamp(),'daily',self::CRON);}
 private function settings(){$s0=(array)get_option(self::OPT,[]);if(get_option('oxygen_kw_all_v1')!=='1'&&class_exists('Oxygen_SEO_Engine')){$kw=array_filter(array_map('trim',preg_split('/[\r\n,،]+/u',(string)($s0['keywords']??"صيانة مكيفات\nغسيل مكيفات\nتركيب مكيفات"))));$all=Oxygen_SEO_Engine::all_keywords();$s0['keywords']=implode("\n",array_values(array_unique(array_merge($kw,$all))));foreach(['new_per_day','seo_per_day','refresh_per_day'] as $k){$s0[$k]=60;}$s0['city']='مكة المكرمة وجدة';update_option(self::OPT,$s0,false);update_option('oxygen_kw_all_v1','1',false);}return wp_parse_args($s0,['new_per_day'=>30,'seo_per_day'=>30,'refresh_per_day'=>30,'auto_publish'=>0,'city'=>'مكة المكرمة','keywords'=>"صيانة مكيفات\nغسيل مكيفات\nتركيب مكيفات",'openai_key'=>'','openai_model'=>'gpt-4o-mini','refresh_after_days'=>30,'last_run'=>'','last_result'=>'']);}
 private function get_home_html(){ $file=plugin_dir_path(__FILE__).'assets/oxygen-maintenance-home.html';if(is_readable($file))$html=file_get_contents($file);else{ $parts=glob(plugin_dir_path(__FILE__).'assets/page-part-*.txt');sort($parts);$encoded='';foreach($parts as $part)$encoded.=trim((string)file_get_contents($part));$html=$encoded?gzdecode(base64_decode($encoded)):'';}if(!$html)return '';
        // The launch mark is inline SVG, so it never depends on a fragile filename or hard-coded attachment ID.
        $html=preg_replace('/banks:\s*\[[\s\S]*?\n\s*\]/','banks: []',$html,1);$html=preg_replace('/SA\d{18,24}/','',$html);$html=str_replace('علي طلعت محمد زيدان','',$html);
        return apply_filters('oxygen_ac_home_html',$html);}
