 <form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="oxygen_ac_save"><?php wp_nonce_field('oxygen_ac_save');?><table class="form-table"><tr><th><label for="new_per_day">مقالات إرشادية جديدة يوميًا</label></th><td><input id="new_per_day" name="new_per_day" type="number" min="0" max="120" value="<?php echo esc_attr($s['new_per_day']);?>" required> من 0 إلى 120</td></tr><tr><th><label for="seo_per_day">صفحات SEO خدمية إضافية يوميًا</label></th><td><input id="seo_per_day" name="seo_per_day" type="number" min="0" max="120" value="<?php echo esc_attr($s['seo_per_day']??30);?>" required> من 0 إلى 120؛ يجب أن تستهدف نية بحث مختلفة ومحتوى مفيدًا، لا نسخ الصفحة نفسها.</td></tr><tr><th><label for="refresh_per_day">مقالات قديمة مختارة عشوائيًا للتحديث يوميًا</label></th><td><input id="refresh_per_day" name="refresh_per_day" type="number" min="0" max="120" value="<?php echo esc_attr($s['refresh_per_day']);?>" required> من 0 إلى 120</td></tr><tr><th>حالة النشر</th><td><label><input type="checkbox" name="auto_publish" value="1" <?php checked((int)$s['auto_publish'],1);?>> نشر تلقائي عند نجاح توليد OpenAI فقط (بدون مفتاح أو عند فشل التوليد تُحفظ المقالات كمسودات للمراجعة)</label></td></tr><tr><th><label for="city">المدينة</label></th><td><select id="city" name="city"><?php foreach(['مكة المكرمة','جدة','مكة المكرمة وجدة'] as $city):?><option value="<?php echo esc_attr($city);?>" <?php selected($s['city'],$city);?>><?php echo esc_html($city);?></option><?php endforeach;?></select></td></tr><tr><th><label for="keywords">الكلمات المفتاحية (كل كلمة في سطر)</label></th><td><textarea id="keywords" name="keywords" rows="9" class="large-text code"><?php echo esc_textarea($s['keywords']);?></textarea></td></tr><tr><th><label for="refresh_after_days">الفاصل قبل تحديث المقال مجددًا</label></th><td><input id="refresh_after_days" name="refresh_after_days" type="number" min="7" max="180" value="<?php echo esc_attr($s['refresh_after_days']);?>"> يومًا</td></tr><tr><th><label for="openai_model">نموذج OpenAI (اختياري)</label></th><td><input id="openai_model" name="openai_model" type="text" value="<?php echo esc_attr($s['openai_model']);?>" class="regular-text"><p>بدون مفتاح أو عند فشل API تُستخدم قوالب عربية داخلية وتُحفظ المقالات كمسودات للمراجعة.</p></td></tr><tr><th><label for="openai_key">مفتاح OpenAI API (اختياري)</label></th><td><input id="openai_key" name="openai_key" type="password" value="" placeholder="اتركه فارغًا للاحتفاظ بالمفتاح الحالي" autocomplete="new-password" class="regular-text"><label><input type="checkbox" name="clear_openai_key" value="1"> حذف المفتاح المحفوظ</label><p>لا يعرض المفتاح المخزن مجددًا داخل الصفحة الإدارية.</p></td></tr></table><?php submit_button('حفظ إعدادات الناشر');?></form><hr><h2>تشغيل يدوي</h2><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="oxygen_ac_run_now"><?php wp_nonce_field('oxygen_ac_run_now');?><?php submit_button('شغّل الناشر الآن','secondary');?></form><h2>نتيجة آخر تشغيل</h2><p><?php echo esc_html($s['last_run']?:'لم يعمل بعد');?></p><pre style="white-space:pre-wrap;background:#fff;padding:12px;border:1px solid #ccd0d4"><?php echo esc_html($s['last_result']?:'لا توجد نتائج بعد.');?></pre><p><a target="_blank" rel="noopener" href="<?php echo esc_url(home_url('/oxygen-ac-home/'));?>">واجهة أكسجين</a> · <a target="_blank" rel="noopener" href="<?php echo esc_url(home_url('/oxygen-ac-articles/'));?>">صفحة المقالات</a></p><h2>استضافة Hostinger</h2><p>للتشغيل حتى عند قلة الزيارات، اضبط Cron يستدعي <code><?php echo esc_html(site_url('/wp-cron.php?doing_wp_cron=1'));?></code> دوريًا إذا كانت الخطة تسمح.</p></div><?php }
 public function save_settings(){if(!current_user_can('manage_options'))wp_die('غير مصرح.');check_admin_referer('oxygen_ac_save');$old=$this->settings();$incoming_key=trim(sanitize_text_field(wp_unslash($_POST['openai_key']??'')));$saved_key=isset($_POST['clear_openai_key'])?'':($incoming_key!==''?$incoming_key:$old['openai_key']);$s=array_merge($old,['new_per_day'=>max(0,min(120,absint($_POST['new_per_day']??30))),'seo_per_day'=>max(0,min(120,absint($_POST['seo_per_day']??30))),'refresh_per_day'=>max(0,min(120,absint($_POST['refresh_per_day']??30))),'auto_publish'=>isset($_POST['auto_publish'])?1:0,'city'=>sanitize_text_field(wp_unslash($_POST['city']??'مكة المكرمة')),'keywords'=>sanitize_textarea_field(wp_unslash($_POST['keywords']??'')),'openai_key'=>$saved_key,'openai_model'=>sanitize_text_field(wp_unslash($_POST['openai_model']??'gpt-4o-mini'))?:'gpt-4o-mini','refresh_after_days'=>max(7,min(180,absint($_POST['refresh_after_days']??30)))]);update_option(self::OPT,$s,false);wp_safe_redirect(add_query_arg('oxygen_message',rawurlencode('تم حفظ الإعدادات.'),admin_url('admin.php?page=oxygen-ac-automation')));exit;}
 public function run_now(){if(!current_user_can('manage_options'))wp_die('غير مصرح.');check_admin_referer('oxygen_ac_run_now');$this->daily_job(true);wp_safe_redirect(add_query_arg('oxygen_message',rawurlencode('اكتمل التشغيل؛ راجع النتائج أسفل لوحة الناشر.'),admin_url('admin.php?page=oxygen-ac-automation')));exit;}
 public function daily_job($force=false){if(!$force&&class_exists('Oxygen_SEO_Engine')&&Oxygen_SEO_Engine::active())return;$s=$this->settings();$today=current_time('Y-m-d');if(!$force&&!empty($s['last_run'])&&substr((string)$s['last_run'],0,10)===$today)return;$created=$this->create_new_articles((int)$s['new_per_day'],$s,0);$seoCreated=$this->create_new_articles((int)($s['seo_per_day']??30),$s,10000,'page');$updated=$this->refresh_old_articles((int)$s['refresh_per_day'],$s,$today);$s['last_run']=current_time('mysql');$s['last_result']=sprintf("مقالات إرشادية جديدة: %d\nصفحات SEO خدمية إضافية: %d\nمقالات قديمة تم تحديثها عشوائيًا: %d\nالإعداد اليومي: %d + %d + %d\nقد يقل العدد إذا لم توجد عناوين فريدة أو مقالات مؤهلة.",$created,$seoCreated,$updated,(int)$s['new_per_day'],(int)($s['seo_per_day']??30),(int)$s['refresh_per_day']);update_option(self::OPT,$s,false);}
 private function keywords($s){$rows=preg_split('/[\r\n,،]+/u',(string)$s['keywords']);$rows=array_values(array_unique(array_filter(array_map('trim',$rows))));return $rows?:['صيانة مكيفات','غسيل مكيفات','تركيب مكيفات','تنظيف مكيفات'];}
 private function topic_pool(){return [['name'=>'صيانة المكيفات','key'=>'صيانة مكيفات','sections'=>['علامات احتياج المكيف للصيانة','فحص الفلاتر ومجرى الهواء','متى تحتاج إلى فني مختص']],['name'=>'غسيل المكيفات','key'=>'غسيل مكيفات','sections'=>['الفرق بين التنظيف السطحي والغسيل','حماية الأجزاء الكهربائية أثناء التنظيف','متى يتكرر تنظيف المكيف']],['name'=>'تركيب المكيفات','key'=>'تركيب مكيفات','sections'=>['اختيار موقع الوحدة الداخلية','تجهيز تصريف المياه والتوصيلات','اختبار التشغيل بعد التركيب']],['name'=>'تنظيف فلاتر المكيف','key'=>'تنظيف مكيفات','sections'=>['خطوات العناية بالفلاتر','أخطاء تقلل تدفق الهواء','علامات تستدعي تنظيف الوحدة']],['name'=>'صيانة مكيف سبليت','key'=>'صيانة مكيفات سبليت','sections'=>['فحص الوحدة الداخلية والخارجية','أسباب ضعف التبريد المحتملة','فحوصات قبل طلب الصيانة']],['name'=>'المكيفات المركزية والداكت','key'=>'صيانة مكيفات مركزية','sections'=>['فحص مجاري الهواء','متابعة الترموستات والتحكم','تنظيم الصيانة الوقائية']],['name'=>'فك ونقل وتركيب المكيف','key'=>'فك ونقل وتركيب مكيف','sections'=>['التجهيز قبل الفك','حماية المواسير والوحدات أثناء النقل','اختبار التسريب والتشغيل']],['name'=>'فحص التبريد والفريون','key'=>'فحص فريون المكيف','sections'=>['لماذا لا يكفي التخمين بشأن الفريون','فحص التسريب قبل الشحن','متى يلزم استدعاء فني']]];}
 private function create_new_articles($limit,$s,$offset=0,$postType='post'){$created=0;$topics=$this->topic_pool();$keys=$this->keywords($s);$cities=$s['city']==='مكة المكرمة وجدة'?['مكة المكرمة','جدة']:[$s['city']];$seed=(int)current_time('z')+((int)current_time('Y')*367);$attempts=0;$max=max(60,$limit*8);while($created<$limit&&$attempts<$max){$n=$seed+$attempts+++(int)$offset;$topic=$topics[$n%count($topics)];$key=$keys[$n%count($keys)];$city=$cities[$n%count($cities)];$opts=[$topic['name'].' في '.$city.': دليل عملي للعناية بالمكيف',$key.' في '.$city.' وأهم خطوات الفحص والتنظيف','متى تحتاج إلى '.$topic['name'].'؟ نصائح لأصحاب المنازل في '.$city,'دليل '.$key.' واختيار وقت الصيانة المناسب في '.$city,$topic['name'].' في '.$city.' مع نصائح لتجنب الأعطال المتكررة','أسباب ضعف التبريد وكيفية فحصها في '.$city,'علامات تستدعي فني '.$topic['name'].' في '.$city,'خطوات الاستعداد لخدمة '.$key.' في '.$city,'أخطاء شائعة عند '.$topic['name'].' وكيف تتجنبها في '.$city,'دليل صاحب المنزل إلى '.$key.' في '.$city,'متى تنظف أو تفحص المكيف؟ دليل '.$city,'أسئلة شائعة عن '.$topic['name'].' في '.$city];$title=$opts[intdiv($n,count($topics))%count($opts)];if(get_page_by_title($title,OBJECT,$postType))continue;$content=$this->openai_article($title,$topic,$key,$city,$s);$ai_ok=is_string($content)&&trim(wp_strip_all_tags($content))!=='';if(!$ai_ok)$content=$this->article_html($title,$topic,$key,$city,$n);$status=(!empty($s['auto_publish'])&&$ai_ok)?'publish':'draft';$cat_id=0;if($postType==='post'){$cat=term_exists('صيانة المكيفات','category');if(!$cat)$cat=wp_insert_term('صيانة المكيفات','category',['slug'=>'air-conditioner-maintenance']);$cat_id=is_array($cat)?(int)$cat['term_id']:(int)$cat;}$id=wp_insert_post(['post_type'=>$postType,'post_status'=>$status,'post_title'=>$title,'post_content'=>$content,'post_excerpt'=>wp_trim_words(wp_strip_all_tags($content),28,'…'),'post_category'=>($postType==='post'&&$cat_id)?[$cat_id]:[],'meta_input'=>['_oxygen_ac_managed'=>'1','_oxygen_ac_content_kind'=>$postType==='page'?'seo_service_page':'guide_article','_oxygen_ac_focus_keyword'=>$key,'_oxygen_ac_created_on'=>current_time('mysql')]],true);if(is_wp_error($id)||!$id)continue;$desc=wp_trim_words(wp_strip_all_tags($content),24,'…');update_post_meta($id,'_yoast_wpseo_metadesc',$desc);update_post_meta($id,'rank_math_description',$desc);update_post_meta($id,'_yoast_wpseo_focuskw',$key);update_post_meta($id,'rank_math_focus_keyword',$key);$created++;}return $created;}
 private function openai_article($title,$topic,$keyword,$city,$s){$key=trim((string)($s['openai_key']??''));if($key==='')return '';$model=sanitize_text_field($s['openai_model']??'gpt-4o-mini');$prompt="اكتب مقالًا عربيًا أصيلًا لا يقل عن 250 كلمة عن {$keyword} في {$city}. العنوان: {$title}. المجال: {$topic['name']}. اكتب HTML فقط بمقدمة عملية وعناوين H2 مرقمة 1،2،3 وعناوين H3 مرقمة 1.1 وهكذا، ونصائح وخاتمة وأسئلة شائعة. استخدم الكلمة المفتاحية طبيعيًا دون حشو. لا تخترع أسعارًا أو ضمانات أو ادعاءات محلية. فحص الكهرباء والفريون من اختصاص فني مؤهل. لا تستخدم H1 أو روابط خارجية أو Markdown.";$r=wp_remote_post('https://api.openai.com/v1/chat/completions',['timeout'=>25,'headers'=>['Authorization'=>'Bearer '.$key,'Content-Type'=>'application/json'],'body'=>wp_json_encode(['model'=>$model,'messages'=>[['role'=>'system','content'=>'أنت محرر محتوى عربي متخصص في صيانة التكييف. اكتب معلومات عملية دقيقة وتجنب حشو الكلمات المفتاحية والتكرار.'],['role'=>'user','content'=>$prompt]],'temperature'=>0.75,'max_tokens'=>1500])]);if(is_wp_error($r)||wp_remote_retrieve_response_code($r)<200||wp_remote_retrieve_response_code($r)>=300)return '';$d=json_decode(wp_remote_retrieve_body($r),true);$text=$d['choices'][0]['message']['content']??'';$word_matches=[];preg_match_all('/\p{L}+/u',wp_strip_all_tags($text),$word_matches);if(!is_string($text)||count($word_matches[0]??[])<200)return '';return wp_kses_post($text);}
 private function article_html($title,$topic,$keyword,$city,$seed){$intro=['تعتمد راحة المنزل وكفاءة استهلاك الطاقة على تدفق هواء مناسب وصيانة تُنفذ في وقتها. يساعد الفحص المنظم على اكتشاف المشكلات مبكرًا، لكنه لا يغني عن تقييم الفني عند وجود عطل كهربائي أو تسريب أو صوت غير معتاد.','قبل طلب الخدمة، دوّن الأعراض التي تلاحظها مثل ضعف التبريد أو نزول الماء أو تكرار توقف الوحدة. هذه الملاحظات تساعد الفني على تضييق احتمالات العطل وتحديد الفحوصات الملائمة دون استبدال قطع سليمة دون داعٍ.','يختلف أسلوب التعامل حسب نوع الجهاز وموقع تركيبه وطبيعة الاستخدام. لذلك من الأفضل اتباع دليل الشركة المصنّعة وفصل الكهرباء قبل أي تنظيف يسمح به دليل المستخدم، وترك الأعمال الفنية الداخلية لمختص مؤهل.'];$checks=['ابدأ بفحص الفلتر وتنظيفه بالطريقة الموضحة في دليل الجهاز، ثم تأكد من عدم وجود ستائر أو أثاث يحجب فتحات الهواء. لا تستخدم مواد كيميائية قوية أو ضغط مياه على الأجزاء الكهربائية، ولا تفتح الدوائر أو تمديدات التبريد بنفسك.','افحص بصريًا المنطقة المحيطة بالوحدة بحثًا عن آثار ماء أو أتربة متراكمة أو تلف ظاهر في العزل. حافظ على خلو المنطقة الخارجية من العوائق مع الالتزام بإجراءات السلامة، ولا تصعد إلى أماكن مرتفعة من دون تجهيز مناسب.','سجّل وقت ظهور المشكلة وهل تحدث عند بداية التشغيل أم بعد فترة. إذا استمرت الأعراض بعد تنظيف الفلتر وإعادة ضبط الإعدادات وفق الدليل، اطلب فحصًا فنيًا بدل تكرار تشغيل الجهاز على نحو قد يزيد المشكلة.'];$advice=['تتضمن الزيارة الفنية الجيدة شرحًا للمشكلة، وبيانًا للفحوصات المقترحة، وتوضيحًا للتكلفة قبل أي إصلاح إضافي. اسأل عن حالة القطعة وسبب تعطلها وما إذا كان الإصلاح أو الاستبدال أنسب، واحتفظ بتفاصيل الخدمة والضمان إن توفر.','تختلف التكلفة بحسب نوع المكيف وعدد الوحدات وسهولة الوصول إليها وحالة القطع المطلوبة. اطلب عرضًا يوضح نطاق العمل وما يشمله السعر، ولا تعتمد سعرًا عامًا قبل معرفة تفاصيل الحالة ومكان الخدمة.','يساعد سجل الصيانة على معرفة تكرار الأعطال وموعد تنظيف الفلاتر والفحص الدوري. في البيوت كثيرة الاستخدام أو المواقع التجارية، قد تحتاج الوحدات إلى مراجعة أكثر انتظامًا حسب ظروف التشغيل وتعليمات الشركة المصنّعة.'];$out='<p>'.esc_html($intro[$seed%count($intro)]).' يتناول هذا الدليل '.esc_html($keyword).' في '.esc_html($city).' بخطوات واضحة تناسب الاستخدام المنزلي وتوضح متى تكون العناية البسيطة كافية ومتى يلزم التواصل مع فني.</p>';$num=1;foreach($topic['sections'] as $i=>$heading){$out.='<h2>'.$num.'. '.esc_html($heading).'</h2><p>'.esc_html($checks[($seed+$i)%count($checks)]).'</p><h3>'.$num.'.1 '.esc_html($i===0?'خطوة عملية يمكن البدء بها':($i===1?'ملاحظات مهمة أثناء الفحص':'متى تطلب المساعدة')).'</h3><p>'.esc_html($advice[($seed+$i+1)%count($advice)]).'</p>';$num++;}$out.='<h2>'.$num.'. أسئلة شائعة حول '.esc_html($keyword).'</h2><h3>'.$num.'.1 هل يمكن تنفيذ كل أعمال الصيانة في المنزل؟</h3><p>يمكن للمستخدم تنظيف الأجزاء التي يسمح بها دليل الجهاز فقط. أما فحص الكهرباء أو فتح دائرة التبريد أو معالجة التسريب فينبغي أن ينفذه فني مؤهل وبالأدوات المناسبة.</p><h3>'.$num.'.2 ما المعلومات التي أجهزها قبل الاتصال؟</h3><p>جهّز نوع المكيف، والعرض الذي تلاحظه، وموقع الوحدة، وموعدًا مناسبًا للزيارة. اطلب شرحًا واضحًا لنطاق العمل والتكلفة المتوقعة قبل بدء الإصلاح.</p><h2>'.($num+1).'. خلاصة الدليل</h2><p>إن متابعة الفلاتر وفتحات الهواء وملاحظة التغييرات في الأداء تساعد على العناية بالمكيف، لكنها لا تضمن زوال كل الأعطال. عند استمرار المشكلة، اجعل التشخيص قائمًا على فحص مناسب بدل التخمين أو إضافة غاز التبريد دون التأكد من السبب. هذه إرشادات عامة، وتعتمد إجراءات السلامة والصيانة النهائية على نوع الجهاز وتعليماته.</p><p><strong>الكلمة المفتاحية:</strong> '.esc_html($keyword).' · <strong>المدينة:</strong> '.esc_html($city).'. تحدد الأسعار والتوافر حسب نوع الوحدة وموقعها وحالة العطل.</p>';return $out;}
 private function refresh_old_articles($limit,$s,$today){
  if(trim((string)($s['openai_key']??''))==='')return 0;
  $all=get_posts(['post_type'=>'post','post_status'=>'publish','numberposts'=>1000,'orderby'=>'modified','order'=>'ASC']);
  $eligible=[];
  $threshold=time()-max(7,(int)$s['refresh_after_days'])*DAY_IN_SECONDS;
  $pattern='/مكيف|تكييف|تكييفات|غسيل|تنظيف|صيانة|تركيب|تبريد|فريون|سبليت|داكت|كونسيلد|مركزي|هواء/u';
  foreach($all as $p){
   if(get_post_meta($p->ID,'_oxygen_ac_refreshed_date',true)===$today)continue;
   $last=get_post_meta($p->ID,'_oxygen_ac_last_refresh',true);
   $changed=get_post_modified_time('U',true,$p);
   if($last&&strtotime($last)>$threshold)continue;
   if(!$last&&$changed>$threshold)continue;
   if(!preg_match($pattern,$p->post_title.' '.wp_strip_all_tags($p->post_content)))continue;
   $eligible[]=$p;
  }
  $updated=0;
  $keys=$this->keywords($s);
  shuffle($eligible);
  foreach(array_slice($eligible,0,max(0,(int)$limit)) as $i=>$p){
   $key=$keys[($i+(int)current_time('z')+(int)$p->ID)%count($keys)];
   $section=$this->openai_refresh_section($p,$key,$s);
   if(!$section)continue;
   $res=wp_update_post(['ID'=>$p->ID,'post_content'=>rtrim($p->post_content)."\\n\\n".$section],true);
   if(is_wp_error($res)||!$res)continue;
   update_post_meta($p->ID,'_oxygen_ac_last_refresh',current_time('mysql'));
   update_post_meta($p->ID,'_oxygen_ac_refreshed_date',$today);
   update_post_meta($p->ID,'_oxygen_ac_focus_keyword',$key);
   $desc=wp_trim_words(wp_strip_all_tags($p->post_content.' '.$section),24,'…');
   update_post_meta($p->ID,'_yoast_wpseo_metadesc',$desc);
   update_post_meta($p->ID,'rank_math_description',$desc);
   update_post_meta($p->ID,'_oxygen_ac_refresh_method','openai_contextual_addition');
   $updated++;
  }
  return $updated;
 }
 private function openai_refresh_section($post,$keyword,$s){
  $apiKey=trim((string)($s['openai_key']??''));
  if($apiKey==='')return '';
  $plain=wp_strip_all_tags($post->post_content);$existing=function_exists('mb_substr')?mb_substr($plain,0,9000):substr($plain,0,9000);
  $prompt="راجع المقال الحالي وأضف له قسمًا تكميليًا أصيلًا باللغة العربية، لا تعِد كتابة المقال كاملًا ولا تكرر الفقرات الموجودة.\\nالعنوان: {$post->post_title}\\nالكلمة المستهدفة: {$keyword}\\nالموقع المستهدف: ".($s['city']??'مكة المكرمة')."\\nالمحتوى الحالي: {$existing}\\nاكتب HTML فقط، 180 إلى 300 كلمة، بعنوان H2 واحد أو اثنين وفقرات/H3 عند الحاجة. يجب أن تضيف خطوات تشخيص آمنة أو قائمة تحضير أو أسئلة عملية جديدة مرتبطة بما في المقال. لا تضف تاريخًا مصطنعًا أو حشو كلمات مفتاحية أو عبارة (عبارات البحث ذات الصلة). لا تخترع أسعارًا أو ضمانات أو تفاصيل محلية أو مواصفات. حافظ على نصائح السلامة: أعمال الكهرباء ودائرة التبريد للفني المؤهل. لا تستخدم H1 أو Markdown أو روابط خارجية.";
  $response=wp_remote_post('https://api.openai.com/v1/chat/completions',['timeout'=>30,'headers'=>['Authorization'=>'Bearer '.$apiKey,'Content-Type'=>'application/json'],'body'=>wp_json_encode(['model'=>sanitize_text_field($s['openai_model']??'gpt-4o-mini'),'messages'=>[['role'=>'system','content'=>'أنت محرر تقني عربي يراجع المقالات الموجودة دون حشو أو تكرار، ويضيف إرشادات مفيدة وسليمة فقط.'],['role'=>'user','content'=>$prompt]],'temperature'=>0.55,'max_tokens'=>900])]);
  if(is_wp_error($response))return '';
  $code=(int)wp_remote_retrieve_response_code($response);
  if($code<200||$code>=300)return '';
  $data=json_decode(wp_remote_retrieve_body($response),true);
  $html=$data['choices'][0]['message']['content']??'';
  if(!is_string($html)||trim($html)==='')return '';
  preg_match_all('/\\p{L}+/u',wp_strip_all_tags($html),$words);
  if(count($words[0]??[])<150)return '';
  if(preg_match('/<h1\\b|عبارات البحث ذات الصلة|keyword stuffing|Lorem ipsum/i',$html))return '';
  return wp_kses_post($html);
 }
}
register_activation_hook(__FILE__,['Oxygen_AC_Automation','activate']);register_deactivation_hook(__FILE__,['Oxygen_AC_Automation','deactivate']);Oxygen_AC_Automation::instance();
